import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import { join } from "node:path";

// What the Android build may ask the system for. android/ is regenerated by
// every prebuild, so app.json is the only place this is decided. Each rule was
// checked against the merged manifest of a release build (aapt2 dump
// permissions): that list is what Google Play shows a rider, and what the
// answers on its forms have to match.

type PluginEntry = string | [string, Record<string, unknown>?];
type AppConfig = {
  expo: {
    plugins: PluginEntry[];
    android: { permissions?: string[]; blockedPermissions?: string[] };
  };
};

const { expo } = JSON.parse(readFileSync(join(process.cwd(), "app.json"), "utf8")) as AppConfig;
const pluginOptions = (name: string): Record<string, unknown> => {
  const entry = expo.plugins.find((plugin) => Array.isArray(plugin) && plugin[0] === name);
  return Array.isArray(entry) ? entry[1] ?? {} : {};
};

{
  // The Expo template asks to draw over other apps, for React Native's
  // developer overlay. A debug build still gets it from its own manifest;
  // a store build has no use for it.
  assert.ok(
    expo.android.blockedPermissions?.includes("android.permission.SYSTEM_ALERT_WINDOW"),
    "A store build must not ask to display over other apps."
  );
}

{
  // A locked phone is told about the next phase by a scheduled notification,
  // which is only on time with an exact alarm.
  assert.ok(
    expo.android.permissions?.includes("android.permission.SCHEDULE_EXACT_ALARM"),
    "Phase alerts on a locked phone need the exact alarm."
  );
  assert.ok(
    !expo.android.permissions?.includes("android.permission.USE_EXACT_ALARM"),
    "Google Play keeps USE_EXACT_ALARM for alarm and calendar apps."
  );
}

{
  // Photos come from the system picker; the camera stays out. The picker's
  // options are sentences (iOS needs them as purpose strings, see
  // tests/store-build-config.test.ts), so on Android only a blocked
  // permission keeps the camera out.
  assert.ok(expo.android.blockedPermissions?.includes("android.permission.CAMERA"), "The camera stays blocked: the app never uses it.");
  assert.ok(!expo.android.permissions?.includes("android.permission.CAMERA"), "The camera must not be asked for.");
  // The microphone is used for one thing (2026-11-27): asking Ralf by voice,
  // turned into text on the phone. expo-speech-recognition asks for it;
  // expo-audio still does not, and plays sound only in the foreground.
  assert.ok(!expo.android.blockedPermissions?.includes("android.permission.RECORD_AUDIO"), "Asking Ralf by voice needs the microphone.");
  assert.ok(pluginOptions("expo-speech-recognition"), "expo-speech-recognition's plugin declares the microphone and speech recognition.");
  assert.equal(pluginOptions("expo-audio").recordAudioAndroid, false, "expo-audio does not ask for the microphone itself.");
  // Background playback adds a foreground service, which Google Play asks an app to declare.
  assert.equal(pluginOptions("expo-audio").enableBackgroundPlayback, false, "No foreground service.");
}

console.log("Android permissions passed.");
